n    <!-- Railing Arc -->\n    <path d=\"M500 1630 Q540 1500 580 1630\" stroke=\"#7C2D12\" stroke-width=\"4.5\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Railing Vertical Posts -->\n    <path d=\"M508 1645 L508 1608 M520 1625 L520 1572 M532 1610 L532 1548 M540 1605 L540 1540 M548 1610 L548 1548 M560 1625 L560 1572 M572 1645 L572 1608\" stroke=\"#7C2D12\" stroke-width=\"3.5\" stroke-linecap=\"round\"/>\n    <!-- Golden Finials (Giboshi) atop the bridge posts -->\n    <circle cx=\"508\" cy=\"1606\" r=\"3.2\" fill=\"#FBBF24\"/>\n    <circle cx=\"520\" cy=\"1570\" r=\"3.4\" fill=\"#FBBF24\"/>\n    <circle cx=\"532\" cy=\"1546\" r=\"3.6\" fill=\"#FBBF24\"/>\n    <circle cx=\"540\" cy=\"1538\" r=\"4.0\" fill=\"#FBBF24\"/>\n    <circle cx=\"548\" cy=\"1546\" r=\"3.6\" fill=\"#FBBF24\"/>\n    <circle cx=\"560\" cy=\"1570\" r=\"3.4\" fill=\"#FBBF24\"/>\n    <circle cx=\"572\" cy=\"1606\" r=\"3.2\" fill=\"#FBBF24\"/>\n    <!-- Little Stone Lantern (Tōrō) on ground next to bridge -->\n    <path d=\"M480 1720 L480 1655 L475 1650 L485 1650 Z\" fill=\"#4A250E\"/>\n    <rect x=\"476\" y=\"1638\" width=\"8\" height=\"12\" rx=\"2\" fill=\"#FEF9C3\" opacity=\".9\"/>\n    <path d=\"M473 1638 L487 1638 L480 1630 Z\" fill=\"#4A250E\"/>\n\n    <!-- Tree 3 (Right Midground Tree) -->\n    \n    <!-- Tree Trunk rooted firmly at y=1720 -->\n    <path d=\"M780 1720 Q774 1580 784 1490\" stroke=\"#4A250E\" stroke-width=\"13\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path d=\"M784 1490 Q764 1440 756 1400\" stroke=\"#4A250E\" stroke-width=\"9\" fill=\"none\" stroke-linecap=\"round\"/>\n    <path d=\"M784 1490 Q800 1440 808 1400\" stroke=\"#4A250E\" stroke-width=\"8\" fill=\"none\" stroke-linecap=\"round\"/>\n    <!-- Multi-lobed billowing sakura clouds (tall in SVG -> round on screen) -->\n    <!-- Base shadow volume -->\n    <ellipse cx=\"762\" cy=\"1420\" rx=\"34.5\" ry=\"119.69999999999999\" fill=\"#B45309\" opacity=\".92\"/>\n    <ellipse cx=\"800\" cy=\"1422\" rx=\"33.12\" ry=